var CONTINUT_COMBINATORICA={};
CONTINUT_COMBINATORICA["principiul-cutiei"]={definitie:"<div class=\"def-box\"><strong>Enunț (Principiul Cutiei / Pigeonhole):</strong> Dacă n+1 obiecte sunt distribuite în n cutii, cel puțin o cutie conține minimum 2 obiecte.</div>",formula_display:"n+1 obiecte, n cutii → ∃cutie cu ≥2 obiecte",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5a1a8a\">4 bile, 3 cutii</text><rect x=\"20\" y=\"70\" width=\"80\" height=\"70\" rx=\"8\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\"/><rect x=\"120\" y=\"70\" width=\"80\" height=\"70\" rx=\"8\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><rect x=\"220\" y=\"70\" width=\"80\" height=\"70\" rx=\"8\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"45\" cy=\"105\" r=\"12\" fill=\"#c8922a\"/><circle cx=\"75\" cy=\"105\" r=\"12\" fill=\"#c8922a\"/><circle cx=\"160\" cy=\"105\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"260\" cy=\"105\" r=\"12\" fill=\"#5a1a8a\"/><text x=\"60\" y=\"160\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">2 bile aici!</text></svg>",intuitiv_text:"Imaginează-ți 4 porumbei care trebuie să doarmă în 3 cuiburi. <span class=\"hl\">Cum sunt mai mulți porumbei decât cuiburi, cel puțin un cuib va avea 2 porumbei</span>, oricum am încerca să-i împărțim. La fel se întâmplă cu orice: dacă ai mai multe obiecte decât locuri unde le pui, un loc va avea sigur mai mult de unul.",intuitiv_nota:"Principiul a fost formulat de Dirichlet în 1834 și își găsește azi aplicații în teoria numerelor (aproximări Diophantine), în combinatorică și în criptografie.",exercitii:[{"q":"Ana are o cutie cu 5 șosete: 2 roșii, 2 albastre și 1 verde. Ea trage șosete pe rând, fără să se uite la culoare. Câte șosete trebuie să tragă ca să fie sigură că are 2 de aceeași culoare?","pasi":["Sunt 3 culori posibile, deci gândim la 3 „cutii”: roșu, albastru, verde.","Dacă trage doar 3 șosete, s-ar putea să nimerească exact una din fiecare culoare - fără nicio pereche.","A patra șosetă trasă trebuie să fie de o culoare deja apărută, pentru că există doar 3 culori în total."],"r":"✓ Sunt necesare <strong>4</strong> șosete pentru a garanta o pereche."},{"q":"Vrem să fim siguri că cel puțin 3 elevi dintr-o clasă s-au născut în aceeași zi a săptămânii (7 zile posibile). Câți elevi trebuie să fie, cel puțin, în clasă?","pasi":["Cu 7 zile ca „cutii”, dacă am avea 14 elevi, s-ar putea ca exact 2 elevi să cadă în fiecare zi - încă nu avem 3 la fel.","Al 15-lea elev, oricare ar fi ziua lui, completează o zi care ajunge la 3 elevi.","Regula generală: pentru a garanta k persoane în aceeași cutie din n cutii, e nevoie de n(k−1)+1 persoane."],"r":"✓ Sunt necesari cel puțin <strong>15</strong> elevi."},{"q":"Avem exact 3 bile și 3 cutii. Este garantat că o cutie va avea cel puțin 2 bile?","pasi":["Principiul cutiei cere ca numărul de obiecte să fie mai mare decât numărul de cutii, adică cel puțin n+1 obiecte pentru n cutii.","Aici avem exact 3 bile și 3 cutii, deci putem pune câte o bilă în fiecare cutie, fără ca vreo cutie să aibă 2.","Cu numere egale garanția nu mai funcționează - acesta este cazul limită al principiului."],"r":"✓ <strong>Nu</strong> este garantat; abia cu 4 bile și 3 cutii devine sigur."},{"q":"Adevărat sau fals: principiul cutiei ne spune exact care cutie va avea mai multe bile.","pasi":["Principiul cutiei este un argument de existență: el asigură doar CĂ există o cutie cu cel puțin 2 obiecte.","El nu spune niciodată care anume cutie este aceea - depinde de cum s-au distribuit obiectele.","La 4 porumbei în 3 cuiburi, oricare dintre cele 3 cuiburi ar putea fi cel aglomerat."],"r":"✓ <strong>Fals</strong> - principiul garantează doar existența, nu și locul exact."},{"q":"La o petrecere sunt 32 de copii și se împart baloane din exact 5 culori diferite (fiecare copil primește un singur balon). Arată că există o culoare aleasă de cel puțin 7 copii.","pasi":["Avem 32 de copii (obiecte) și 5 culori (cutii).","Dacă împărțirea ar fi cât mai echilibrată, fiecare culoare ar ajunge la cel mult 6 copii, adică în total cel mult 5×6=30 copii.","Cum sunt 32 de copii, mai mulți decât 30, cel puțin o culoare trebuie aleasă de cel puțin 7 copii."],"r":"✓ Există sigur o culoare cu cel puțin <strong>7</strong> copii."}]};
CONTINUT_COMBINATORICA["binomul-lui-newton"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Expansiunea puterii a n-a a unui binom, cu coeficienți binomiali C(n,k)=n!/(k!(n-k)!).</div>",formula_display:"(a+b)ⁿ = ∑_{k=0}^n C(n,k)·aⁿ⁻ᵏ·bᵏ",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">Triunghiul lui Pascal</text><g font-size=\"11\" text-anchor=\"middle\" font-family=\"sans-serif\"><circle cx=\"150\" cy=\"30\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"150\" y=\"34\" fill=\"#5a1a8a\">1</text><circle cx=\"130\" cy=\"62\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"130\" y=\"66\" fill=\"#5a1a8a\">1</text><circle cx=\"170\" cy=\"62\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"170\" y=\"66\" fill=\"#5a1a8a\">1</text><circle cx=\"110\" cy=\"94\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"110\" y=\"98\" fill=\"#5a1a8a\">1</text><circle cx=\"150\" cy=\"94\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"150\" y=\"98\" fill=\"#5a1a8a\">2</text><circle cx=\"190\" cy=\"94\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"190\" y=\"98\" fill=\"#5a1a8a\">1</text><circle cx=\"90\" cy=\"126\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"90\" y=\"130\" fill=\"#5a1a8a\">1</text><circle cx=\"130\" cy=\"126\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"130\" y=\"130\" fill=\"#5a1a8a\">3</text><circle cx=\"170\" cy=\"126\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"170\" y=\"130\" fill=\"#5a1a8a\">3</text><circle cx=\"210\" cy=\"126\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"210\" y=\"130\" fill=\"#5a1a8a\">1</text><circle cx=\"70\" cy=\"158\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"70\" y=\"162\" fill=\"#5a1a8a\">1</text><circle cx=\"110\" cy=\"158\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"110\" y=\"162\" fill=\"#5a1a8a\">4</text><circle cx=\"150\" cy=\"158\" r=\"14\" fill=\"#c8922a\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"150\" y=\"162\" fill=\"#ffffff\">6</text><circle cx=\"190\" cy=\"158\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"190\" y=\"162\" fill=\"#5a1a8a\">4</text><circle cx=\"230\" cy=\"158\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"230\" y=\"162\" fill=\"#5a1a8a\">1</text></g><text x=\"150\" y=\"182\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">C(4,2)=6</text></svg>",intuitiv_text:"Când desfaci (a+b) înmulțit cu el însuși de mai multe ori, apar tot felul de combinații de a-uri și b-uri. <span class=\"hl\">C(n,k) numără în câte moduri poți alege exact k litere „b” din cele n paranteze</span>, restul rămânând „a”. Aceste numere formează chiar triunghiul lui Pascal: fiecare număr este suma celor două de deasupra lui.",intuitiv_nota:"Newton a descoperit formula la 22 de ani (1665), extinzând-o la puteri fracționare. Apare în probabilitate (distribuția binomială), combinatorică și analiză.",exercitii:[{"q":"Dezvoltă complet (a+b)³.","pasi":["Fiecare termen are forma C(3,k)·a³⁻ᵏ·bᵏ, pentru k=0,1,2,3.","Coeficienții sunt C(3,0)=1, C(3,1)=3, C(3,2)=3, C(3,3)=1 (rândul 3 din triunghiul lui Pascal).","Adunând termenii obținem a³+3a²b+3ab²+b³."],"r":"✓ <strong>a³+3a²b+3ab²+b³</strong>"},{"q":"Un termen din dezvoltarea lui (a+b)⁵ este C(5,k)·a²·b³. Ce valoare are k și cât este coeficientul?","pasi":["Exponentul lui b în termenul general C(5,k)aⁿ⁻ᵏbᵏ este chiar k.","Cum exponentul lui b este 3, rezultă direct k=3 (și verificăm: exponentul lui a este 5−3=2, exact cât cere enunțul).","Coeficientul este C(5,3)=5!/(3!·2!)=10."],"r":"✓ k=<strong>3</strong>, coeficient=<strong>10</strong>"},{"q":"Cât este (a+b)⁰ și ce spune formula pentru n=0?","pasi":["Orice sumă a+b ridicată la puterea 0 este, prin convenție, egală cu 1.","Formula dă suma unui singur termen, cel cu k=0: C(0,0)·a⁰·b⁰=1·1·1=1.","Cazul n=0 confirmă deci convenția: (a+b)⁰=1."],"r":"✓ <strong>1</strong>"},{"q":"Adevărat sau fals: coeficienții C(n,k) sunt mereu simetrici, adică C(n,k)=C(n,n−k).","pasi":["Simetria vine din faptul că a alege k litere „b” este totuna cu a lăsa n−k litere „a” pe locurile rămase.","De exemplu, la n=4: C(4,1)=4 și C(4,3)=4, deci sunt egale.","În triunghiul lui Pascal, această simetrie se vede direct: fiecare rând citit de la stânga la dreapta este identic cu cel citit de la dreapta la stânga."],"r":"✓ <strong>Adevărat</strong>"},{"q":"La o petrecere cu 4 copii, gazda vrea să știe în total în câte grupuri diferite (de la 0 la 4 copii) îi poate aduna pe rând pe copii, pentru un joc. Câte grupuri diferite există în total, inclusiv grupul gol și grupul cu toți 4?","pasi":["Numărul de grupuri cu exact k copii este C(4,k); trebuie adunate toate, de la k=0 la k=4.","Suma ∑C(4,k) este exact valoarea (1+1)⁴, obținută punând a=b=1 în binomul lui Newton.","(1+1)⁴=2⁴=16."],"r":"✓ În total <strong>16</strong> grupuri diferite"}]};
CONTINUT_COMBINATORICA["principiul-excluderii-includerii"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Cardinalul reuniunii a n mulțimi este suma cardinalelor minus suma intersecțiilor perechi plus suma intersecțiilor triple..., alternând semnele.</div>",formula_display:"|A∪B∪C|=|A|+|B|+|C|-|A∩B|-|A∩C|-|B∩C|+|A∩B∩C|",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"120\" cy=\"100\" r=\"65\" fill=\"#5a1a8a\" fill-opacity=\"0.35\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"190\" cy=\"100\" r=\"65\" fill=\"#c8922a\" fill-opacity=\"0.4\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"85\" y=\"60\" font-size=\"14\" fill=\"#5a1a8a\" font-weight=\"bold\">A</text><text x=\"225\" y=\"60\" font-size=\"14\" fill=\"#c8922a\" font-weight=\"bold\">B</text><text x=\"155\" y=\"104\" font-size=\"11\" fill=\"#3a0a5a\" text-anchor=\"middle\">A∩B</text><text x=\"150\" y=\"175\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">|A∪B|=|A|+|B|−|A∩B|</text></svg>",intuitiv_text:"La o petrecere, unii copii au tricou roșu, alții au pălărie, iar câțiva au și tricou roșu și pălărie. Dacă adunăm „copii cu tricou roșu” cu „copii cu pălărie”, pe cei care au ambele îi numărăm de două ori. <span class=\"hl\">Ca să aflăm corect câți copii au măcar unul dintre cele două lucruri, trebuie să scădem o dată copiii numărați de două ori</span>.",intuitiv_nota:"Principiul a fost dezvoltat de Euler și Sylvester în secolele XVIII-XIX și apare azi în combinatorică, de la numărarea funcțiilor surjective până la permutările fără puncte fixe (derajamente).",exercitii:[{"q":"Într-o clasă, 12 elevi joacă fotbal, 9 elevi joacă baschet, iar 4 elevi joacă ambele sporturi. Câți elevi joacă cel puțin un sport?","pasi":["Adunăm mai întâi cei de la fotbal și cei de la baschet: 12+9=21.","Cei 4 care joacă ambele sporturi au fost numărați de două ori în această sumă, așa că îi scădem o singură dată.","21−4=17 elevi joacă cel puțin un sport."],"r":"✓ <strong>17</strong> elevi"},{"q":"Într-o clasă de 25 de elevi, 15 învață engleza, 14 învață franceza, iar toți cei 25 învață cel puțin una dintre cele două limbi. Câți elevi învață ambele limbi?","pasi":["Știm că |A∪B|=25, |A|=15, |B|=14 și formula |A∪B|=|A|+|B|−|A∩B|.","Înlocuind: 25=15+14−|A∩B|, adică 25=29−|A∩B|.","De aici |A∩B|=29−25=4."],"r":"✓ <strong>4</strong> elevi învață ambele limbi"},{"q":"Dacă A și B nu au niciun element comun (|A∩B|=0), ce devine formula |A∪B|=|A|+|B|−|A∩B|?","pasi":["Punem |A∩B|=0 direct în formulă: |A∪B|=|A|+|B|−0.","Scăderea zero nu schimbă nimic, deci rămâne |A∪B|=|A|+|B|.","Acesta este cazul cel mai simplu: dacă mulțimile nu se suprapun deloc, pur și simplu adunăm."],"r":"✓ <strong>|A∪B|=|A|+|B|</strong> (simpla adunare)"},{"q":"Adevărat sau fals: pentru trei mulțimi, este suficient să adunăm |A|+|B|+|C| și să scădem toate perechile de intersecții, fără să mai adăugăm nimic altceva.","pasi":["Dacă doar scădem perechile |A∩B|, |A∩C|, |B∩C|, elementele din toate cele trei mulțimi deodată (A∩B∩C) ajung scăzute de 3 ori, deși inițial fuseseră adunate de 3 ori.","Rezultatul net pentru acele elemente ar fi 3−3=0, adică ele ar dispărea complet din numărătoare, ceea ce e greșit.","De aceea trebuie readăugat o dată |A∩B∩C|, ca elementele din toate trei să rămână numărate exact o dată."],"r":"✓ <strong>Fals</strong> - trebuie readăugată |A∩B∩C|"},{"q":"La un concurs, 30 de elevi participă la probe de matematică, română sau desen: 14 la matematică, 12 la română, 10 la desen; 5 la matematică și română, 4 la matematică și desen, 3 la română și desen; 2 la toate trei probe. Câți elevi participă la cel puțin o probă?","pasi":["Adunăm mai întâi probele individuale: 14+12+10=36.","Scădem perechile de intersecții: 36−(5+4+3)=36−12=24.","Readăugăm elevii numărați la toate trei probe: 24+2=26."],"r":"✓ <strong>26</strong> elevi"}]};
CONTINUT_COMBINATORICA["formula-lui-cayley-arbori"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Numărul de arbori cu etichetă (marcați) pe n noduri distincte este n^(n-2).</div>",formula_display:"τ(Kₙ) = nⁿ⁻²",diagrama:"<svg viewBox=\"0 0 260 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"130\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">un arbore dintre cei 16 posibili (n=4)</text><line x1=\"70\" y1=\"50\" x2=\"70\" y2=\"150\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><line x1=\"70\" y1=\"50\" x2=\"190\" y2=\"150\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><line x1=\"190\" y1=\"50\" x2=\"70\" y2=\"150\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><line x1=\"70\" y1=\"150\" x2=\"190\" y2=\"150\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><line x1=\"70\" y1=\"50\" x2=\"190\" y2=\"50\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"190\" y1=\"50\" x2=\"190\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"190\" y1=\"150\" x2=\"70\" y2=\"150\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"70\" cy=\"50\" r=\"14\" fill=\"#5a1a8a\"/><circle cx=\"190\" cy=\"50\" r=\"14\" fill=\"#5a1a8a\"/><circle cx=\"70\" cy=\"150\" r=\"14\" fill=\"#5a1a8a\"/><circle cx=\"190\" cy=\"150\" r=\"14\" fill=\"#5a1a8a\"/><text x=\"70\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">1</text><text x=\"190\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">2</text><text x=\"70\" y=\"155\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">3</text><text x=\"190\" y=\"155\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">4</text><text x=\"130\" y=\"190\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">muchiile aurii = un arbore (3 muchii, fără ciclu)</text></svg>",intuitiv_text:"Imaginează 4 case numerotate 1, 2, 3, 4 într-un sat. Vrei să legi toate casele prin poteci, dar fără să faci vreo buclă (un ocol care se închide) și fără să lași vreo casă neconectată. <span class=\"hl\">Există foarte multe moduri diferite de a face asta - pentru 4 case, exact 16</span>. Formula lui Cayley numără toate aceste rețele posibile.",intuitiv_nota:"Formula a fost demonstrată de Arthur Cayley în 1889. O demonstrație ulterioară, mai elegantă, folosește codul Prüfer, care pune în corespondență bijectivă arborii pe n noduri cu șirurile de lungime n-2 din {1,...,n}.",exercitii:[{"q":"Câți arbori marcați (cu noduri numerotate) există pe 4 noduri?","pasi":["Aplicăm formula n^(n−2) cu n=4.","4^(4−2)=4²=16.","Fiecare astfel de arbore folosește exact 3 muchii (n−1) și leagă toate cele 4 noduri fără nicio buclă."],"r":"✓ <strong>16</strong> arbori"},{"q":"Pentru ce valoare a lui n formula n^(n−2) dă exact 1 arbore?","pasi":["Căutăm n astfel încât n^(n−2)=1.","Pentru n=2: 2^(2−2)=2⁰=1 - potrivit!","Are sens: pe 2 noduri există un singur arbore posibil, format din muchia care leagă cele 2 noduri."],"r":"✓ n=<strong>2</strong>"},{"q":"Ce se întâmplă pentru n=1 (un singur nod, fără nicio muchie)? Este acesta considerat un arbore?","pasi":["Formula algebrică 1^(1−2)=1^(−1) nu se calculează direct în mod obișnuit, deci n=1 este un caz special.","Totuși, combinatoric, un singur nod fără nicio muchie este considerat prin convenție un arbore trivial.","Prin convenție se acceptă că există exact 1 arbore pe 1 nod, deși formula nu se aplică algebric neschimbată."],"r":"✓ Prin convenție, există <strong>1</strong> arbore trivial pe 1 nod"},{"q":"Adevărat sau fals: orice graf conex cu n noduri și exact n−1 muchii este un arbore.","pasi":["Un arbore este, prin definiție, un graf conex fără cicluri.","Dacă un graf conex are exact n−1 muchii, nu mai are loc pentru nicio muchie „în plus” care ar crea un ciclu - orice muchie suplimentară ar depăși n−1.","Se demonstrează astfel că un graf conex cu exact n−1 muchii este automat fără cicluri, deci este un arbore."],"r":"✓ <strong>Adevărat</strong>"},{"q":"O companie de telefonie vrea să conecteze 5 orașe cu cabluri de fibră optică, fără nicio buclă (rută redundantă), astfel încât toate orașele să fie conectate direct sau indirect. În câte moduri diferite se poate proiecta rețeaua, dacă orașele sunt distincte și contează exact care oraș se leagă de care?","pasi":["Aceasta este exact situația din formula lui Cayley, cu n=5 orașe.","Calculăm 5^(5−2)=5³.","5³=125."],"r":"✓ <strong>125</strong> moduri diferite"}]};
CONTINUT_COMBINATORICA["teorema-lui-ramsey"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Pentru orice k,l există n=R(k,l) astfel că orice 2-colorare a muchiilor lui Kₙ conține fie un K_k monocromatic roșu, fie un K_l monocromatic albastru.</div>",formula_display:"∀k,l ∃R(k,l): orice 2-colorare Kₙ conține K_k sau K̄_l",diagrama:"<svg viewBox=\"0 0 300 210\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">6 persoane: mereu apar 3 care se cunosc</text><g transform=\"translate(0,10)\"><line x1=\"220\" y1=\"100\" x2=\"185\" y2=\"40\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"185\" y1=\"40\" x2=\"115\" y2=\"40\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"115\" y1=\"40\" x2=\"80\" y2=\"100\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"80\" y1=\"100\" x2=\"115\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"115\" y1=\"160\" x2=\"185\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"185\" y1=\"160\" x2=\"220\" y2=\"100\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><line x1=\"220\" y1=\"100\" x2=\"115\" y2=\"40\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"115\" y1=\"40\" x2=\"115\" y2=\"160\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"115\" y1=\"160\" x2=\"220\" y2=\"100\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"220\" cy=\"100\" r=\"11\" fill=\"#c8922a\"/><circle cx=\"185\" cy=\"40\" r=\"11\" fill=\"#5a1a8a\"/><circle cx=\"115\" cy=\"40\" r=\"11\" fill=\"#c8922a\"/><circle cx=\"80\" cy=\"100\" r=\"11\" fill=\"#5a1a8a\"/><circle cx=\"115\" cy=\"160\" r=\"11\" fill=\"#c8922a\"/><circle cx=\"185\" cy=\"160\" r=\"11\" fill=\"#5a1a8a\"/></g><text x=\"150\" y=\"200\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">triunghi auriu = 3 persoane care se cunosc reciproc</text></svg>",intuitiv_text:"La o petrecere cu 6 copii, oricare doi copii ori se cunosc, ori nu se cunosc. Oricum ar fi „aranjate” cunoștințele dintre ei, <span class=\"hl\">se găsesc mereu 3 copii care se cunosc toți între ei, sau 3 copii care nu se cunosc deloc între ei</span>. Cu 6 copii, nu se poate evita asta - oricât am încerca.",intuitiv_nota:"Teorema poartă numele lui Frank Ramsey, care a demonstrat-o în 1930, dar valorile exacte R(k,l) rămân extrem de greu de calculat - R(5,5), de pildă, este încă necunoscut.",exercitii:[{"q":"La 6 persoane, arată de ce trebuie să existe 3 care se cunosc reciproc sau 3 care nu se cunosc deloc.","pasi":["Alegem o persoană oarecare; ea are alte 5 persoane în jur, pe care fie le cunoaște, fie nu le cunoaște.","Din cele 5, prin principiul cutiei, persoana noastră are cel puțin 3 cunoștințe sau cel puțin 3 necunoștințe printre ele.","Presupunem că are 3 cunoștințe: dacă oricare 2 dintre acestea 3 se cunosc între ele, avem deja 3 persoane care se cunosc toate; dacă nu, acele 2 formează o pereche de necunoscuți, iar împreună cu persoana inițială obținem tot un grup relevant. Raționamentul simetric funcționează și pentru necunoștințe."],"r":"✓ Cu 6 persoane, concluzia este <strong>garantată</strong> - acesta e motivul pentru care R(3,3)=6"},{"q":"Se știe că R(3,4)=9. Cu 8 persoane la o petrecere, este garantat că există 3 care se cunosc reciproc sau 4 care nu se cunosc deloc?","pasi":["R(3,4)=9 înseamnă că 9 este cel mai mic număr de persoane care garantează concluzia.","Cu 8 persoane, mai puține decât pragul de 9, se poate construi o situație în care nu apar nici 3 cunoscuți reciproc, nici 4 necunoscuți reciproc.","Deci, cu doar 8 persoane, concluzia NU este garantată - e nevoie de cel puțin 9."],"r":"✓ <strong>Nu</strong> este garantat cu 8 persoane; e nevoie de 9"},{"q":"Cât este R(4,2)? (Cazul special în care unul dintre numere este 2.)","pasi":["R(k,2) cere fie un grup de k persoane care se cunosc toate, fie doar 2 persoane care nu se cunosc (o singură pereche de necunoscuți).","La exact n=k persoane, ori toate perechile se cunosc între ele (și atunci avem grupul de k), ori există măcar o pereche care nu se cunoaște (și atunci avem cei 2 necunoscuți).","Așadar R(k,2)=k întotdeauna; pentru k=4 obținem R(4,2)=4."],"r":"✓ R(4,2)=<strong>4</strong>"},{"q":"Adevărat sau fals: teorema lui Ramsey ne spune exact câte persoane trebuie să cunoască fiecare, nu doar câte persoane trebuie să fie la petrecere.","pasi":["Teorema garantează doar CĂ, la un anumit număr de persoane, structura căutată (grup de cunoscuți sau de necunoscuți) apare undeva.","Ea nu spune NICIODATĂ cine anume cunoaște pe cine - asta depinde de situația concretă, nu de teoremă.","Este, la fel ca principiul cutiei, un rezultat de existență, nu unul constructiv."],"r":"✓ <strong>Fals</strong> - teorema garantează doar existența, nu detaliile"},{"q":"Într-o excursie sunt 6 elevi. Fiecare pereche de elevi ori s-a mai întâlnit înainte, ori nu. Profesorul spune că există sigur 3 elevi care s-au întâlnit toți între ei sau 3 elevi care nu s-au întâlnit deloc între ei. Are dreptate?","pasi":["Situația descrisă este exact R(3,3), unde „cunoștință” înseamnă „s-au mai întâlnit”.","Se știe că R(3,3)=6, adică exact numărul de elevi din excursie.","Cu exact 6 persoane, concluzia este întotdeauna garantată."],"r":"✓ <strong>Da</strong>, profesorul are dreptate"}]};
CONTINUT_COMBINATORICA["teorema-hall-cuplaje"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Graful bipartit G=(A∪B,E) admite un cuplaj care saturează A (acoperă toți nodii din A) dacă și numai dacă pentru orice S⊆A: |N(S)|≥|S| (condiția Hall).</div>",formula_display:"Cuplaj saturant A ↔ |N(S)| ≥ |S| ∀S⊆A",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">cuplaj care saturează A</text><line x1=\"60\" y1=\"40\" x2=\"240\" y2=\"75\" stroke=\"#5a1a8a\" stroke-width=\"1.5\" opacity=\"0.6\"/><line x1=\"60\" y1=\"100\" x2=\"240\" y2=\"75\" stroke=\"#5a1a8a\" stroke-width=\"1.5\" opacity=\"0.6\"/><line x1=\"60\" y1=\"160\" x2=\"240\" y2=\"125\" stroke=\"#5a1a8a\" stroke-width=\"1.5\" opacity=\"0.6\"/><line x1=\"60\" y1=\"40\" x2=\"240\" y2=\"25\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"60\" y1=\"100\" x2=\"240\" y2=\"125\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"60\" y1=\"160\" x2=\"240\" y2=\"175\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"60\" cy=\"40\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"60\" cy=\"100\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"60\" cy=\"160\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"240\" cy=\"25\" r=\"13\" fill=\"#c8922a\"/><circle cx=\"240\" cy=\"75\" r=\"13\" fill=\"#c8922a\"/><circle cx=\"240\" cy=\"125\" r=\"13\" fill=\"#c8922a\"/><circle cx=\"240\" cy=\"175\" r=\"13\" fill=\"#c8922a\"/><text x=\"60\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">1</text><text x=\"60\" y=\"104\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">2</text><text x=\"60\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">3</text><text x=\"240\" y=\"29\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">a</text><text x=\"240\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">b</text><text x=\"240\" y=\"129\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">c</text><text x=\"240\" y=\"179\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">d</text><text x=\"30\" y=\"20\" font-size=\"11\" fill=\"#5a1a8a\">A</text><text x=\"270\" y=\"20\" font-size=\"11\" fill=\"#c8922a\">B</text></svg>",intuitiv_text:"Într-o clasă, fiecare băiat vrea să danseze cu una dintre fetele pe care le cunoaște. Dacă orice grup de băieți cunoaște, împreună, cel puțin tot atâtea fete câți băieți sunt în grup, atunci <span class=\"hl\">toți băieții pot găsi câte o parteneră diferită de dans</span>. Dacă însă un grup de băieți cunoaște mai puține fete decât sunt ei, cel puțin unul dintre ei rămâne fără parteneră.",intuitiv_nota:"Teorema a fost demonstrată de Philip Hall în 1935 și are aplicații în teoria distribuțiilor (sisteme de reprezentanți distincți), fiind folosită și pentru a demonstra existența pătratelor latine.",exercitii:[{"q":"A={1,2,3}, B={a,b,c,d}. N(1)={a,b}, N(2)={b,c}, N(3)={c,d}. Există un cuplaj care saturează A?","pasi":["Verificăm condiția Hall pentru fiecare submulțime S a lui A: pentru S de un singur element, |N(S)|=2≥1, deci e în regulă.","Pentru perechi: N({1,2})={a,b,c} are 3 elemente ≥2; N({1,3})={a,b,c,d} are 4≥2; N({2,3})={b,c,d} are 3≥2.","Pentru toată mulțimea: N({1,2,3})={a,b,c,d} are 4 elemente ≥3, deci condiția Hall este satisfăcută peste tot."],"r":"✓ <strong>Da</strong>, de exemplu cuplajul 1-a, 2-b, 3-c"},{"q":"Modifică exemplul astfel încât N(3)={a,b} (elevul 3 cunoaște doar fete deja cunoscute de 1 și 2, nu o fată nouă). Mai există cuplaj saturant pentru A?","pasi":["Verificăm submulțimea S={1,2,3}: vecinii lor reuniți sunt N(S)={a,b,c}, adică 3 elemente.","Stai, dacă N(3)={a,b}, atunci N({1,2,3})=N(1)∪N(2)∪N(3)={a,b}∪{b,c}∪{a,b}={a,b,c}, tot 3 elemente pentru 3 băieți, deci ar părea suficient.","Dar dacă în loc reducem la N(3)={a,b} și presupunem că și N(2) rămâne {a,b} (nu {b,c}), atunci N({1,2,3})={a,b}, doar 2 elemente pentru 3 băieți: 2&lt;3, condiția Hall eșuează și nu mai există cuplaj saturant."],"r":"✓ Dacă vecinătatea comună a tuturor scade sub 3, cuplajul saturant <strong>nu mai există</strong>"},{"q":"Ce înseamnă condiția Hall dacă A este mulțimea vidă (niciun băiat)?","pasi":["Singura submulțime a mulțimii vide este ea însăși, S=∅.","Vecinătatea mulțimii vide este tot vidă, N(∅)=∅, deci |N(∅)|=0.","Condiția cere 0≥0, ceea ce este adevărat automat - deci condiția Hall este satisfăcută trivial (vacuu), iar cuplajul vid saturează, evident, mulțimea vidă."],"r":"✓ Condiția Hall este <strong>satisfăcută automat</strong> pentru A vidă"},{"q":"Adevărat sau fals: dacă fiecare băiat din A cunoaște cel puțin o fată, atunci condiția Hall este automat satisfăcută.","pasi":["Condiția Hall trebuie verificată pentru TOATE submulțimile lui A, nu doar pentru fiecare element în parte.","Contraexemplu: dacă N(1)=N(2)=N(3)={a} (toți trei cunosc doar aceeași fată), fiecare băiat individual are un vecin, dar submulțimea S={1,2,3} are |N(S)|=1&lt;3.","Condiția Hall eșuează pentru această submulțime, deși fiecare băiat, luat separat, cunoaște pe cineva."],"r":"✓ <strong>Fals</strong> - trebuie verificate toate submulțimile, nu doar elementele individuale"},{"q":"5 muncitori și 5 sarcini sunt aranjați într-un cerc: muncitorul i știe să facă sarcina i și sarcina i+1 (iar muncitorul 5 știe sarcina 5 și sarcina 1). Există un cuplaj perfect, adică fiecare muncitor primește o sarcină diferită pe care o știe face?","pasi":["Observăm că fiecare muncitor i cunoaște direct sarcina cu același număr, i.","Putem atribui pur și simplu muncitorul i la sarcina i, pentru fiecare i de la 1 la 5.","Această atribuire este validă (fiecare muncitor primește o sarcină pe care o cunoaște) și fiecare sarcină este folosită o singură dată, deci este un cuplaj perfect."],"r":"✓ <strong>Da</strong>, de exemplu muncitorul i primește sarcina i"}]};
CONTINUT_COMBINATORICA["recurente-liniare"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Recurența liniară aₙ=c₁aₙ₋₁+…+cₖaₙ₋ₖ are soluția generală exprimată prin rădăcinile ecuației caracteristice λᵏ-c₁λᵏ⁻¹-…-cₖ=0.</div>",formula_display:"aₙ = c₁r₁ⁿ+c₂r₂ⁿ+…+cₖrₖⁿ (rᵢ rădăcini distincte)",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">șirul Fibonacci: fiecare bară e suma ultimelor două</text><line x1=\"10\" y1=\"170\" x2=\"270\" y2=\"170\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><rect x=\"20\" y=\"158\" width=\"30\" height=\"12\" fill=\"#5a1a8a\"/><rect x=\"60\" y=\"158\" width=\"30\" height=\"12\" fill=\"#5a1a8a\"/><rect x=\"100\" y=\"146\" width=\"30\" height=\"24\" fill=\"#5a1a8a\"/><rect x=\"140\" y=\"134\" width=\"30\" height=\"36\" fill=\"#5a1a8a\"/><rect x=\"180\" y=\"110\" width=\"30\" height=\"60\" fill=\"#5a1a8a\"/><rect x=\"220\" y=\"74\" width=\"30\" height=\"96\" fill=\"#c8922a\"/><text x=\"35\" y=\"153\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">1</text><text x=\"75\" y=\"153\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">1</text><text x=\"115\" y=\"141\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">2</text><text x=\"155\" y=\"129\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">3</text><text x=\"195\" y=\"105\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">5</text><text x=\"235\" y=\"69\" text-anchor=\"middle\" font-size=\"11\" fill=\"#c8922a\">8</text><path d=\"M155,130 Q195,50 230,70\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><path d=\"M195,106 Q210,60 232,72\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><text x=\"150\" y=\"190\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">a6=a5+a4 (8=5+3)</text></svg>",intuitiv_text:"Fiecare număr nou se face din cele dinainte, ca o rețetă simplă: la șirul lui Fibonacci - 1, 1, 2, 3, 5, 8... - fiecare număr este suma celor două de dinaintea lui (1+1=2, 1+2=3, 2+3=5, 3+5=8). <span class=\"hl\">Privești ultimii doi pași, îi aduni, și afli următorul</span>. O recurență liniară este exact o astfel de rețetă, scrisă cu litere în loc de numere.",intuitiv_nota:"Metoda a fost pusă la punct de De Moivre și Euler în secolul XVIII și apare azi în analiza algoritmilor (recurențe de complexitate), în fizică (oscilații) și în teoria semnalelor.",exercitii:[{"q":"Se știe că aₙ=aₙ₋₁+2aₙ₋₂, cu a₁=1 și a₂=1. Calculează a₃, a₄ și a₅ aplicând direct rețeta pas cu pas.","pasi":["a₃=a₂+2a₁=1+2×1=3.","a₄=a₃+2a₂=3+2×1=5.","a₅=a₄+2a₃=5+2×3=11."],"r":"✓ a₃=<strong>3</strong>, a₄=<strong>5</strong>, a₅=<strong>11</strong>"},{"q":"Se știe că aₙ=2aₙ₋₁ și a₃=12. Află a₁ (mergând înapoi în recurență).","pasi":["Din recurență, a₃=2a₂, deci a₂=a₃/2=12/2=6.","La fel, a₂=2a₁, deci a₁=a₂/2=6/2=3.","Am mers înapoi cu recurența pentru a afla valoarea de start."],"r":"✓ a₁=<strong>3</strong>"},{"q":"Recurența aₙ=2aₙ₋₁−aₙ₋₂ are ecuația caracteristică λ²−2λ+1=0. Ce este special la rădăcinile acestei ecuații?","pasi":["Rezolvăm: λ²−2λ+1=(λ−1)²=0.","Ecuația are o singură rădăcină, λ=1, dar „dublă” (apare de două ori).","În acest caz special, soluția generală nu mai este doar A×1ⁿ, ci A+Bn (se adaugă un factor „n” suplimentar) - altfel am pierde o parte din soluțiile posibile."],"r":"✓ Rădăcină <strong>dublă</strong> λ=1; soluția generală devine aₙ=A+Bn"},{"q":"Adevărat sau fals: pentru orice recurență liniară, soluția generală este întotdeauna o sumă simplă de puteri rᵢⁿ, indiferent dacă rădăcinile ecuației caracteristice se repetă sau nu.","pasi":["Atât timp cât toate rădăcinile ecuației caracteristice sunt diferite între ele, soluția este într-adevăr o sumă de puteri rᵢⁿ.","Dar dacă o rădăcină se repetă (ca la exercițiul anterior, unde λ=1 apărea de două ori), trebuie adăugat un factor suplimentar de tip n, n², etc.","Deci afirmația nu este corectă în general - depinde dacă rădăcinile sunt distincte sau repetate."],"r":"✓ <strong>Fals</strong>"},{"q":"Jocul Turnul din Hanoi cu n discuri necesită T(n)=2T(n−1)+1 mutări, cu T(1)=1. Câte mutări sunt necesare pentru 4 discuri?","pasi":["T(2)=2×T(1)+1=2×1+1=3.","T(3)=2×T(2)+1=2×3+1=7.","T(4)=2×T(3)+1=2×7+1=15."],"r":"✓ <strong>15</strong> mutări"}]};
CONTINUT_COMBINATORICA["numerele-catalan"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Al n-lea număr Catalan Cₙ numără parantezările valide ale unui produs de n+1 factori, triangulațiile unui poligon convex cu n+2 laturi, drumurile Dyck de lungime 2n și arborii binari compleți cu n+1 frunze.</div>",formula_display:"Cₙ = (1/(n+1))·C(2n,n)",diagrama:"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">un drum Dyck valid (n=3): sus-sus-sus-jos-jos-jos</text><line x1=\"20\" y1=\"140\" x2=\"280\" y2=\"140\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><polyline points=\"30,140 70,115 110,90 150,65 190,90 230,115 270,140\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"30\" cy=\"140\" r=\"6\" fill=\"#5a1a8a\"/><circle cx=\"70\" cy=\"115\" r=\"6\" fill=\"#5a1a8a\"/><circle cx=\"110\" cy=\"90\" r=\"6\" fill=\"#5a1a8a\"/><circle cx=\"150\" cy=\"65\" r=\"6\" fill=\"#c8922a\"/><circle cx=\"190\" cy=\"90\" r=\"6\" fill=\"#5a1a8a\"/><circle cx=\"230\" cy=\"115\" r=\"6\" fill=\"#5a1a8a\"/><circle cx=\"270\" cy=\"140\" r=\"6\" fill=\"#5a1a8a\"/><text x=\"150\" y=\"165\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">drumul nu coboară niciodată sub linia punctată</text></svg>",intuitiv_text:"Imaginează-te urcând și coborând niște trepte, cu o singură regulă: nu ai voie să ajungi mai jos decât locul de unde ai plecat. Numărul lui Catalan numără în câte moduri diferite poți face o asemenea plimbare de trepte, fără să încâlci regula. <span class=\"hl\">Aceeași regulă simplă explică și alte jocuri, ca așezarea corectă a parantezelor sau tăierea unui poligon în triunghiuri</span> - de aceea același șir de numere apare peste tot: 1, 1, 2, 5, 14, 42...",intuitiv_nota:"Euler a studiat problema triangulațiilor poligoanelor, iar Eugène Catalan (1838) a redescoperit șirul în studiul parantezărilor. Azi apar în informatică (arbori de parsare, structuri de date) și combinatorică enumerativă.",exercitii:[{"q":"Calculează C₄ folosind formula Cₙ=(1/(n+1))·C(2n,n), și spune câte triangulații are un hexagon (poligon cu 6 laturi).","pasi":["Pentru n=4 avem nevoie de C(2·4,4)=C(8,4).","C(8,4)=8!/(4!·4!)=70.","Împărțim la n+1=5: C₄=70/5=14, deci un hexagon are exact 14 triangulații posibile."],"r":"✓ C₄=<strong>14</strong> triangulații"},{"q":"Se știe că un produs de mai mulți factori are exact 5 parantezări valide posibile. Câți factori are acel produs?","pasi":["Numărul de parantezări valide ale unui produs cu n+1 factori este Cₙ, deci căutăm n astfel încât Cₙ=5.","Din șirul cunoscut C₀=1, C₁=1, C₂=2, C₃=5, observăm că Cₙ=5 exact pentru n=3.","Produsul are atunci n+1=4 factori."],"r":"✓ Produsul are <strong>4</strong> factori (de exemplu a·b·c·d)"},{"q":"Calculează C₀ și C₁ direct din formulă și explică de ce amândouă sunt egale cu 1.","pasi":["C₀=(1/(0+1))·C(0,0)=1·1=1; acesta corespunde unui produs cu un singur factor (n+1=1), care nu are nicio paranteză de pus.","C₁=(1/(1+1))·C(2,1)=(1/2)·2=1; acesta corespunde unui produs cu 2 factori, a·b, care se poate scrie într-un singur fel.","Ambele cazuri au un singur rezultat posibil, pentru că nu există nicio alegere reală de făcut atunci când sunt doar 1 sau 2 factori."],"r":"✓ C₀=<strong>1</strong> și C₁=<strong>1</strong>"},{"q":"Adevărat sau fals: numerele lui Catalan numără doar parantezările corecte ale unui produs și nu au legătură cu alte tipuri de numărare.","pasi":["Numerele lui Catalan numără, de fapt, mai multe structuri diferite deodată: parantezări corecte, triangulații de poligoane, drumuri Dyck și arbori binari compleți.","Toate aceste probleme, deși par diferite la prima vedere, dau exact același șir de numere 1, 1, 2, 5, 14, 42...","De aceea numerele lui Catalan sunt considerate unul dintre cele mai „universale” șiruri din combinatorică."],"r":"✓ <strong>Fals</strong> - aceleași numere apar în multe probleme diferite"},{"q":"La un ghișeu de bilete, un bilet costă 5 lei. La coadă stau 3 persoane cu bancnote de exact 5 lei și 3 persoane cu bancnote de exact 10 lei, amestecate într-o ordine oarecare, iar ghișeul începe fără niciun leu. Pentru ca fiecare persoană cu bancnotă de 10 lei să primească imediat rest de 5 lei, la orice moment numărul persoanelor cu 5 lei deja servite trebuie să fie cel puțin egal cu numărul persoanelor cu 10 lei deja servite. În câte ordini posibile ale celor 6 persoane se poate întâmpla asta?","pasi":["Gândim fiecare persoană cu 5 lei ca pe un pas „sus” și fiecare persoană cu 10 lei ca pe un pas „jos”, exact ca la un drum Dyck de lungime 6.","Condiția ca ghișeul să aibă mereu destul rest disponibil este exact condiția ca drumul să nu coboare niciodată sub nivelul de start.","Numărul unor asemenea drumuri, cu 3 pași sus și 3 pași jos, este C₃=5."],"r":"✓ Există exact <strong>5</strong> ordini valide"}]};
CONTINUT_COMBINATORICA["numerele-stirling"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Numărul Stirling de speța a doua S(n,k) numără partițiile unei mulțimi cu n elemente în exact k submulțimi nevide. Numărul Stirling de speța întâi (neînsemnat) c(n,k) numără permutările a n elemente cu exact k cicluri.</div>",formula_display:"S(n,k)=k·S(n−1,k)+S(n−1,k−1), c(n,k)=(n−1)·c(n−1,k)+c(n−1,k−1)",diagrama:"<svg viewBox=\"0 0 300 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"14\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5a1a8a\">o partiție a lui {1,2,3,4} în 2 grupuri (S(4,2)=7 în total)</text><rect x=\"35\" y=\"45\" width=\"180\" height=\"60\" rx=\"30\" fill=\"#5a1a8a\" fill-opacity=\"0.15\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"240\" cy=\"75\" r=\"28\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"75\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"120\" cy=\"75\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"180\" cy=\"75\" r=\"13\" fill=\"#5a1a8a\"/><circle cx=\"240\" cy=\"75\" r=\"13\" fill=\"#c8922a\"/><text x=\"60\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">1</text><text x=\"120\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">2</text><text x=\"180\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">3</text><text x=\"240\" y=\"79\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">4</text><text x=\"125\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">grupul {1,2,3}</text><text x=\"240\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">grupul {4}</text></svg>",intuitiv_text:"Ai 4 jucării și vrei să le pui în cutii, dar nicio cutie nu are voie să rămână goală: S(n,k) numără în câte moduri poți face asta dacă folosești exact k cutii, fără să conteze ordinea jucăriilor din interior. Există și un „văr” al lui S(n,k), numit c(n,k): în loc de cutii, copiii se prind de mână și formează cercuri (fiecare copil ține de mâna următorului) - c(n,k) numără în câte moduri poți forma exact k asemenea cercuri din n copii. <span class=\"hl\">Amândouă numără feluri de „grupare”, doar regula de grupare este diferită</span>.",intuitiv_nota:"Introduse de James Stirling (1730) în studiul seriilor factoriale. Azi apar în combinatorică (partiții, cicluri de permutări), analiza algoritmilor și teoria numerelor.",exercitii:[{"q":"Calculează S(4,2) - numărul de partiții ale mulțimii {1,2,3,4} în 2 grupuri nevide.","pasi":["Pentru k=2 există o formulă simplă: S(n,2)=2ⁿ⁻¹−1.","Pentru n=4 obținem S(4,2)=2³−1=8−1=7.","Cele 7 partiții sunt: {1}{2,3,4}, {2}{1,3,4}, {3}{1,2,4}, {4}{1,2,3}, {1,2}{3,4}, {1,3}{2,4}, {1,4}{2,3}."],"r":"✓ S(4,2)=<strong>7</strong>"},{"q":"Se știe că S(n,n−1)=10, adică o partiție a unei mulțimi cu n elemente în n−1 grupuri (toate grupurile au un singur element, în afară de o singură pereche). Află valoarea lui n.","pasi":["Într-o partiție cu n−1 grupuri dintr-o mulțime de n elemente, exact un grup are 2 elemente, iar restul au câte un singur element.","Numărul acestor partiții este egal cu numărul de perechi posibile, adică S(n,n−1)=C(n,2).","Punem C(n,2)=10, adică n(n−1)/2=10, deci n(n−1)=20; testăm n=5: 5·4=20, potrivit."],"r":"✓ n=<strong>5</strong>"},{"q":"Calculează S(3,3) și S(3,1), și explică de ce amândouă sunt egale cu 1.","pasi":["S(3,3) numără partițiile lui {1,2,3} în exact 3 grupuri nevide; singura posibilitate este ca fiecare element să fie singur în grupul lui: {1}{2}{3}.","S(3,1) numără partițiile în exact 1 grup; singura posibilitate este ca toate elementele să fie împreună: {1,2,3}.","În ambele cazuri extreme nu există nicio alegere reală de făcut, deci există o singură partiție posibilă."],"r":"✓ S(3,3)=<strong>1</strong> și S(3,1)=<strong>1</strong>"},{"q":"Adevărat sau fals: S(n,k) și c(n,k) numără exact același lucru, doar cu notații diferite.","pasi":["S(4,2) numără partițiile lui {1,2,3,4} în 2 grupuri nevide, fără ordine în interior, și am calculat mai sus că S(4,2)=7.","c(4,2) numără permutările lui {1,2,3,4} cu exact 2 cicluri; folosind recurența c(n,k)=(n−1)·c(n−1,k)+c(n−1,k−1) obținem c(4,2)=3·c(3,2)+c(3,1)=3·3+2=11.","Cum 7 și 11 sunt valori diferite pentru aceiași n și k, S(n,k) și c(n,k) numără lucruri diferite, chiar dacă ambele satisfac recurențe asemănătoare cu triunghiul lui Pascal."],"r":"✓ <strong>Fals</strong> - S(4,2)=7, dar c(4,2)=11"},{"q":"La un carnaval, 5 copii trebuie împărțiți în exact 3 echipe, fiecare echipă trebuind să aibă cel puțin un copil; nu contează numele echipelor, doar cine e cu cine. În câte moduri diferite pot fi formate echipele?","pasi":["Această situație este exact S(5,3), numărul de partiții ale unei mulțimi cu 5 elemente în 3 grupuri nevide.","Folosind recurența S(n,k)=k·S(n−1,k)+S(n−1,k−1) obținem S(5,3)=3·S(4,3)+S(4,2).","Din exercițiile anterioare știm S(4,2)=7, iar S(4,3)=6 (o pereche și doi copii singuri, adică C(4,2)=6 alegeri pentru pereche); deci S(5,3)=3·6+7=25."],"r":"✓ Există <strong>25</strong> de moduri diferite de a forma echipele"}]};
CONTINUT_COMBINATORICA["teorema-lui-erdos-szekeres"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Orice șir de (r−1)(s−1)+1 numere reale distincte conține fie un subșir crescător de lungime r, fie un subșir descrescător de lungime s.</div>",formula_display:"șir de (r−1)(s−1)+1 termeni distincți → subșir crescător de r sau descrescător de s",diagrama:"<svg viewBox=\"0 0 320 180\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"160\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">șirul 5,3,4,1,2 - subșirul auriu 5,3,1 este descrescător</text><polyline points=\"40,40 100,80 160,60 220,120 280,100\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.5\"/><polyline points=\"40,40 100,80 220,120\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"40\" cy=\"40\" r=\"10\" fill=\"#c8922a\"/><circle cx=\"100\" cy=\"80\" r=\"10\" fill=\"#c8922a\"/><circle cx=\"160\" cy=\"60\" r=\"9\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"220\" cy=\"120\" r=\"10\" fill=\"#c8922a\"/><circle cx=\"280\" cy=\"100\" r=\"9\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><text x=\"40\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">5</text><text x=\"100\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">3</text><text x=\"160\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">4</text><text x=\"220\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">1</text><text x=\"280\" y=\"155\" text-anchor=\"middle\" font-size=\"11\" fill=\"#5a1a8a\">2</text></svg>",intuitiv_text:"Pune niște cărți de joc, cu numere diferite, una după alta pe masă. Oricât ai încerca să le amesteci, dacă sunt destule cărți, <span class=\"hl\">vei găsi mereu, ascuns printre ele, fie un grup de cărți care cresc în ordine, fie un grup care descresc în ordine</span>. Cu cât vrei grupuri mai lungi, cu atât ai nevoie de mai multe cărți pe masă ca să fii sigur că apar.",intuitiv_nota:"Paul Erdős și George Szekeres (1935) au redescoperit rezultatul lucrând la o problemă de geometrie (poligoane convexe în mulțimi de puncte) și au dat prima demonstrație folosind principiul cutiei.",exercitii:[{"q":"Pentru r=3 și s=3, ce lungime minimă trebuie să aibă un șir de numere distincte pentru a garanta un subșir crescător de lungime 3 sau un subșir descrescător de lungime 3?","pasi":["Aplicăm formula (r−1)(s−1)+1 cu r=3 și s=3.","(3−1)·(3−1)+1=2·2+1=5.","Așadar orice șir de cel puțin 5 numere distincte conține sigur un subșir crescător de 3 sau descrescător de 3; cu doar 4 numere, acest lucru nu mai este garantat."],"r":"✓ <strong>5</strong> termeni"},{"q":"Se știe că, pentru r=4, pragul calculat cu formula (r−1)(s−1)+1 este de 10 termeni. Află valoarea lui s.","pasi":["Înlocuim r=4 și pragul 10 în formulă: (4−1)(s−1)+1=10.","De aici 3(s−1)=9, deci s−1=3.","Rezultă s=4."],"r":"✓ s=<strong>4</strong>"},{"q":"Ce se întâmplă pentru r=2 și s=2? Calculează pragul și explică ce înseamnă acest caz special.","pasi":["Aplicăm formula (r−1)(s−1)+1 cu r=2 și s=2: (2−1)(2−1)+1=1+1=2.","Pragul de 2 termeni este cel mai mic caz posibil: cu doar 2 numere distincte, ele sunt fie în ordine crescătoare, fie în ordine descrescătoare - nu există a treia variantă.","Acesta este cazul limită al teoremei, în care garanția devine aproape banală."],"r":"✓ prag = <strong>2</strong> termeni (cazul cel mai simplu posibil)"},{"q":"Adevărat sau fals: teorema lui Erdős-Szekeres garantează că, în același șir, apar întotdeauna simultan atât un subșir crescător lung, cât și unul descrescător lung.","pasi":["Teorema garantează doar că apare CEL PUȚIN unul dintre cele două tipuri de subșir - fie cel crescător de lungime r, fie cel descrescător de lungime s.","Nu este obligatoriu ca ambele tipuri de subșir să apară simultan în același șir.","De exemplu, șirul 1,2,3,4,5 (strict crescător) nu conține niciun subșir descrescător mai lung de 1 element, deși conține un subșir crescător foarte lung."],"r":"✓ <strong>Fals</strong> - teorema garantează doar apariția a cel puțin unuia dintre cele două tipuri"},{"q":"Un atlet aleargă 10 curse și obține timpuri diferite la fiecare cursă (fără egalitate între ele). Antrenorul spune că, oricare ar fi rezultatele, există sigur fie 4 curse cu timpuri constant crescătoare, fie 4 curse cu timpuri constant descrescătoare. Are dreptate antrenorul?","pasi":["Pentru r=4 și s=4, pragul din teorema lui Erdős-Szekeres este (4−1)(4−1)+1=9+1=10.","Cu exact 10 curse, numărul de rezultate distincte atinge exact acest prag.","Deci antrenorul are dreptate: cu 10 curse este garantată apariția fie a unui subșir de 4 timpuri constant crescătoare, fie a unui subșir de 4 timpuri constant descrescătoare."],"r":"✓ <strong>Da</strong>, antrenorul are dreptate - cu exact 10 curse pragul este atins"}]};
CONTINUT_COMBINATORICA["numerele-bell"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Numărul lui Bell Bₙ numără toate partițiile posibile ale unei mulțimi cu n elemente în submulțimi nevide, indiferent de numărul de părți: Bₙ=∑ₖ S(n,k).</div>",formula_display:"Bₙ = ∑_{k=0}^{n} S(n,k)",diagrama:"<svg viewBox=\"0 0 320 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"160\" y=\"14\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5a1a8a\">B₃=5: toate partițiile posibile ale mulțimii {1,2,3}</text><circle cx=\"40\" cy=\"45\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"40\" cy=\"72\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"40\" cy=\"99\" r=\"7\" fill=\"#5a1a8a\"/><text x=\"40\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#5a1a8a\">{1}{2}{3}</text><line x1=\"100\" y1=\"45\" x2=\"100\" y2=\"72\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"100\" cy=\"45\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"100\" cy=\"72\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"100\" cy=\"99\" r=\"7\" fill=\"#5a1a8a\"/><text x=\"100\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#5a1a8a\">{1,2}{3}</text><line x1=\"160\" y1=\"45\" x2=\"160\" y2=\"99\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"160\" cy=\"45\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"160\" cy=\"72\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"160\" cy=\"99\" r=\"7\" fill=\"#5a1a8a\"/><text x=\"160\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#5a1a8a\">{1,3}{2}</text><line x1=\"220\" y1=\"72\" x2=\"220\" y2=\"99\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"220\" cy=\"45\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"220\" cy=\"72\" r=\"7\" fill=\"#5a1a8a\"/><circle cx=\"220\" cy=\"99\" r=\"7\" fill=\"#5a1a8a\"/><text x=\"220\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#5a1a8a\">{2,3}{1}</text><line x1=\"280\" y1=\"45\" x2=\"280\" y2=\"72\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><line x1=\"280\" y1=\"72\" x2=\"280\" y2=\"99\" stroke=\"#c8922a\" stroke-width=\"2.5\"/><circle cx=\"280\" cy=\"45\" r=\"7\" fill=\"#c8922a\"/><circle cx=\"280\" cy=\"72\" r=\"7\" fill=\"#c8922a\"/><circle cx=\"280\" cy=\"99\" r=\"7\" fill=\"#c8922a\"/><text x=\"280\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c8922a\">{1,2,3}</text></svg>",intuitiv_text:"Ai 3 jucării și vrei să le grupezi în „echipe”, dar poți alege orice număr de echipe - una mare cu toate jucăriile, sau mai multe echipe mici, cum vrei tu, doar ca nicio echipă să nu rămână goală. Numărul lui Bell, Bₙ, numără <span class=\"hl\">în câte moduri diferite poți face toate aceste grupări posibile, indiferent câte echipe ies</span>. Pentru 3 jucării există exact 5 moduri: toate separate, grupate câte 2 în trei feluri diferite, sau toate împreună.",intuitiv_nota:"Numite după Eric Temple Bell (1934), deși au fost studiate anterior de Dobiński. Satisfac formula lui Dobiński (o sumă infinită cu e⁻¹) și recurența triunghiului lui Bell.",exercitii:[{"q":"Calculează B₄ folosind ∑ₖS(4,k), cu S(4,0..4)=0,1,7,6,1.","pasi":["Bell adună toate numerele Stirling de speța a doua pentru n=4: B₄=S(4,0)+S(4,1)+S(4,2)+S(4,3)+S(4,4).","Înlocuind valorile cunoscute: B₄=0+1+7+6+1.","0+1+7+6+1=15."],"r":"✓ B₄=<strong>15</strong>"},{"q":"Se știe că numărul de moduri de a grupa o mulțime de jucării (indiferent de câte grupuri ies) este 15. Câte jucării sunt în mulțime?","pasi":["Căutăm n astfel încât Bₙ=15.","Din șirul cunoscut B₀=1, B₁=1, B₂=2, B₃=5, B₄=15, observăm că valoarea 15 apare exact la n=4.","Deci mulțimea are 4 jucării."],"r":"✓ n=<strong>4</strong> jucării"},{"q":"Câte partiții are o mulțime cu 0 elemente (mulțimea vidă) și câte are o mulțime cu 1 element?","pasi":["O mulțime vidă are o singură partiție posibilă: partiția vidă, pentru că nu există niciun element de grupat; deci B₀=1.","O mulțime cu un singur element are, de asemenea, o singură partiție posibilă: acel element formează singur un grup; deci B₁=1.","Aceste două cazuri extreme sunt punctele de plecare ale întregului șir al lui Bell."],"r":"✓ B₀=<strong>1</strong> și B₁=<strong>1</strong>"},{"q":"Adevărat sau fals: Bₙ este întotdeauna egal cu cea mai mare valoare S(n,k) dintre toate valorile posibile ale lui k.","pasi":["Bₙ este SUMA tuturor numerelor S(n,k) pentru k de la 0 la n, nu doar cea mai mare valoare dintre ele.","De exemplu, pentru n=4: S(4,1)=1, S(4,2)=7, S(4,3)=6, S(4,4)=1, iar cea mai mare valoare individuală este 7 (nu 15).","Suma tuturor acestor valori este B₄=1+7+6+1=15, diferită de cea mai mare valoare individuală."],"r":"✓ <strong>Fals</strong> - Bₙ este suma tuturor valorilor S(n,k), nu doar maximul"},{"q":"La o petrecere cu 3 copii, gazda vrea să îi împartă în echipe pentru diverse jocuri, fără nicio restricție asupra numărului de echipe, doar ca nicio echipă să nu rămână fără copii. Câte moduri diferite de împărțire există în total?","pasi":["Această situație este exact B₃, numărul total de partiții ale unei mulțimi cu 3 elemente, indiferent de câte grupuri rezultă.","Enumerăm toate posibilitățile: {1}{2}{3}, {1,2}{3}, {1,3}{2}, {2,3}{1}, {1,2,3} - în total 5 moduri diferite.","Aceasta confirmă B₃=5."],"r":"✓ Există <strong>5</strong> moduri diferite de a împărți cei 3 copii"}]};
CONTINUT_COMBINATORICA["teorema-lui-konig-cuplaje"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Într-un graf bipartit G=(A∪B,E), dimensiunea maximă a unui cuplaj este egală cu dimensiunea minimă a unei acoperiri cu vârfuri (mulțime de vârfuri care atinge fiecare muchie).</div>",formula_display:"max |cuplaj(G)| = min |acoperire cu vârfuri(G)|, G bipartit",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5a1a8a\">cuplaj maxim = acoperire minimă = 2</text><line x1=\"70\" y1=\"50\" x2=\"230\" y2=\"50\" stroke=\"#5a1a8a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\" opacity=\"0.6\"/><line x1=\"70\" y1=\"50\" x2=\"230\" y2=\"140\" stroke=\"#c8922a\" stroke-width=\"3\"/><line x1=\"70\" y1=\"140\" x2=\"230\" y2=\"50\" stroke=\"#c8922a\" stroke-width=\"3\"/><circle cx=\"70\" cy=\"50\" r=\"14\" fill=\"#c8922a\"/><circle cx=\"70\" cy=\"140\" r=\"14\" fill=\"#5a1a8a\"/><circle cx=\"230\" cy=\"50\" r=\"14\" fill=\"#c8922a\"/><circle cx=\"230\" cy=\"140\" r=\"14\" fill=\"#5a1a8a\"/><text x=\"70\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">1</text><text x=\"70\" y=\"145\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">2</text><text x=\"230\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">a</text><text x=\"230\" y=\"145\" text-anchor=\"middle\" font-size=\"12\" fill=\"#ffffff\">b</text><text x=\"40\" y=\"24\" font-size=\"11\" fill=\"#5a1a8a\">A</text><text x=\"260\" y=\"24\" font-size=\"11\" fill=\"#5a1a8a\">B</text><text x=\"150\" y=\"175\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">noduri aurii {1,a} = acoperire minimă; muchii aurii = cuplaj maxim</text></svg>",intuitiv_text:"Într-o clasă, câțiva băieți vor să danseze, fiecare cu o fată pe care o cunoaște. Un „cuplaj” înseamnă să formăm cât mai multe perechi băiat-fată, fiecare copil dansând cu un singur partener. O „acoperire” înseamnă să alegem cât mai puțini copii (băieți sau fete) astfel încât fiecare pereche posibilă de dans să aibă cel puțin un copil ales în ea. <span class=\"hl\">Teorema lui Kőnig spune că, într-un grup împărțit clar în două tabere, cele mai multe perechi posibile de dans sunt exact tot atâtea câți copii minim trebuie aleși pentru acoperire</span>.",intuitiv_nota:"Dénes Kőnig (1931) a demonstrat rezultatul, esențial pentru algoritmi de cuplaj (Hopcroft–Karp) și pentru probleme de alocare (asignarea sarcinilor). Egalitatea nu se păstrează, în general, la grafuri non-bipartite.",exercitii:[{"q":"Într-un graf bipartit complet K₂,₃, cu A={1,2} și B={a,b,c} (toate cele 6 muchii posibile prezente), găsește dimensiunea cuplajului maxim și a acoperirii minime cu vârfuri.","pasi":["Cuplajul poate folosi fiecare vârf din A o singură dată, iar A are doar 2 vârfuri, deci cuplajul maxim nu poate depăși dimensiunea 2; alegem, de exemplu, {1-a, 2-b}.","Pentru acoperire, alegem cele 2 vârfuri din A, adică {1,2}; cum fiecare dintre cele 6 muchii pornește dintr-un vârf din A, toate sunt atinse.","Cuplajul găsit are 2 muchii, iar acoperirea găsită are 2 vârfuri, și niciuna dintre ele nu poate fi mai mică (A are doar 2 vârfuri); teorema este confirmată: max cuplaj = min acoperire = 2."],"r":"✓ max cuplaj = min acoperire = <strong>2</strong>"},{"q":"Se știe că, într-un graf bipartit, acoperirea minimă cu vârfuri are dimensiunea 3. Fără să cunoști restul grafului, ce poți spune despre dimensiunea cuplajului maxim?","pasi":["Teorema lui Kőnig spune că, în orice graf bipartit, dimensiunea cuplajului maxim este întotdeauna egală cu dimensiunea acoperirii minime cu vârfuri.","Cum acoperirea minimă are dimensiunea 3, aceasta este valoarea garantată și pentru cuplajul maxim, indiferent de forma exactă a grafului.","Nu este nevoie să cunoaștem muchiile exacte ale grafului pentru a afla această valoare - egalitatea funcționează pentru orice graf bipartit."],"r":"✓ Cuplajul maxim are, de asemenea, dimensiunea <strong>3</strong>"},{"q":"Ce se întâmplă cu cuplajul maxim și acoperirea minimă într-un graf bipartit fără nicio muchie (A și B există, dar nu sunt legate deloc)?","pasi":["Fără nicio muchie, nu se poate forma nicio pereche, deci cuplajul maxim are dimensiunea 0.","Acoperirea cu vârfuri trebuie să atingă fiecare muchie a grafului, dar cum nu există nicio muchie, mulțimea vidă de vârfuri este deja o acoperire validă.","Deci acoperirea minimă are, de asemenea, dimensiunea 0, confirmând teorema și în acest caz extrem."],"r":"✓ max cuplaj = min acoperire = <strong>0</strong>"},{"q":"Adevărat sau fals: egalitatea dintre cuplajul maxim și acoperirea minimă (teorema lui Kőnig) este valabilă pentru orice graf, nu doar pentru cele bipartite.","pasi":["Pe triunghiul K₃ (3 vârfuri, toate cele 3 muchii prezente, un graf care NU este bipartit), cuplajul maxim are dimensiunea 1, pentru că orice a doua muchie aleasă ar folosi un vârf deja ocupat.","Acoperirea minimă cu vârfuri pe K₃ are însă dimensiunea 2, pentru că un singur vârf atinge doar 2 din cele 3 muchii, lăsând a treia muchie neatinsă.","Cum 1 este diferit de 2 în acest exemplu, egalitatea nu se păstrează pentru grafuri generale - teorema lui Kőnig este specifică grafurilor bipartite."],"r":"✓ <strong>Fals</strong> - pe K₃ (non-bipartit) cuplajul maxim este 1, dar acoperirea minimă este 2"},{"q":"O firmă are 4 angajați și 4 proiecte, așezate într-un cerc: angajatul i este calificat pentru proiectele i și i+1 (angajatul 4 este calificat pentru proiectele 4 și 1). Firma vrea să repartizeze fiecare angajat la un proiect diferit pe care îl cunoaște. Care este dimensiunea maximă a repartizării (cuplajului) și a acoperirii minime?","pasi":["Fiecare angajat i poate fi repartizat direct la proiectul i, folosind exact 4 perechi angajat-proiect diferite: (1,1),(2,2),(3,3),(4,4); acesta este un cuplaj perfect de dimensiune 4.","Cum toți cei 4 angajați sunt folosiți, cuplajul maxim nu poate depăși 4, pentru că nu sunt mai mult de 4 angajați disponibili.","Prin teorema lui Kőnig, acoperirea minimă cu vârfuri trebuie să aibă, la rândul ei, exact dimensiunea 4."],"r":"✓ max cuplaj = min acoperire = <strong>4</strong>"}]};
CONTINUT_COMBINATORICA["formula-lui-vandermonde"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Identitatea lui Vandermonde exprimă coeficientul binomial al unei sume ca o sumă de produse de coeficienți binomiali: C(m+n,k)=∑ᵢ C(m,i)·C(n,k−i).</div>",formula_display:"C(m+n,k) = ∑_{i=0}^{k} C(m,i)·C(n,k−i)",diagrama:"<svg viewBox=\"0 0 300 190\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5a1a8a\">alegem k=2 din grupul A (3) + grupul B (2)</text><rect x=\"20\" y=\"50\" width=\"140\" height=\"60\" rx=\"10\" fill=\"#5a1a8a\" fill-opacity=\"0.08\" stroke=\"#5a1a8a\" stroke-width=\"1.5\"/><text x=\"90\" y=\"45\" text-anchor=\"middle\" font-size=\"10\" fill=\"#5a1a8a\">grup A (m=3)</text><rect x=\"180\" y=\"50\" width=\"100\" height=\"60\" rx=\"10\" fill=\"#c8922a\" fill-opacity=\"0.1\" stroke=\"#c8922a\" stroke-width=\"1.5\"/><text x=\"230\" y=\"45\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">grup B (n=2)</text><circle cx=\"50\" cy=\"80\" r=\"13\" fill=\"#c8922a\"/><circle cx=\"90\" cy=\"80\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"130\" cy=\"80\" r=\"13\" fill=\"none\" stroke=\"#5a1a8a\" stroke-width=\"2\"/><circle cx=\"210\" cy=\"80\" r=\"13\" fill=\"#c8922a\"/><circle cx=\"250\" cy=\"80\" r=\"13\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2\"/><text x=\"150\" y=\"145\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">o alegere posibilă: 1 din A + 1 din B (termenul i=1)</text></svg>",intuitiv_text:"Ai un bol cu 3 bomboane roșii și un alt bol cu 2 bomboane albastre, iar tu vrei să alegi în total 2 bomboane, din oricare bol. Poți alege 2 roșii și 0 albastre, sau 1 roșie și 1 albastră, sau 0 roșii și 2 albastre. <span class=\"hl\">Dacă aduni toate aceste variante posibile, obții exact același rezultat ca și cum ai fi ales direct 2 bomboane dintr-un bol mare cu toate cele 5 bomboane la un loc</span> - asta spune formula lui Vandermonde.",intuitiv_nota:"Numită după Alexandre-Théophile Vandermonde (1772), deși cazul particular era cunoscut lui Zhu Shijie (sec. XIV). Cazul m=n=k dă identitatea ∑ᵢC(n,i)²=C(2n,n).",exercitii:[{"q":"Verifică identitatea lui Vandermonde pentru m=2, n=2, k=2, calculând ambele părți ale egalității.","pasi":["Partea stângă: C(m+n,k)=C(4,2)=4!/(2!·2!)=6.","Partea dreaptă: ∑ᵢC(2,i)·C(2,2−i)=C(2,0)C(2,2)+C(2,1)C(2,1)+C(2,2)C(2,0)=1·1+2·2+1·1=1+4+1=6.","Cele două părți sunt egale, 6=6, confirmând identitatea pentru acest caz."],"r":"✓ <strong>6=6</strong>"},{"q":"Se știe că C(m+2,2)=15, cu n=2 fixat. Găsește valoarea lui m.","pasi":["C(m+2,2)=(m+2)(m+1)/2, deci punem (m+2)(m+1)/2=15, adică (m+2)(m+1)=30.","Căutăm două numere consecutive al căror produs este 30: 6·5=30, deci m+2=6 și m+1=5.","Din m+1=5 rezultă m=4."],"r":"✓ m=<strong>4</strong>"},{"q":"Ce se întâmplă cu identitatea când n=0? Verifică pentru m=5, n=0, k=3.","pasi":["Cu n=0, singurul termen din sumă care nu se anulează este cel cu i=k, pentru că C(0,k−i) este 0 pentru orice i diferit de k (nu putem alege un număr diferit de 0 elemente dintr-o mulțime vidă).","Termenul rămas este C(m,k)·C(0,0)=C(m,k)·1=C(m,k).","Pentru m=5, k=3: C(5,3)=10, iar partea stângă C(5+0,3)=C(5,3)=10 - identică, cum era de așteptat."],"r":"✓ Identitatea se reduce la <strong>C(m,k)=C(m,k)</strong>, adevărat trivial"},{"q":"Adevărat sau fals: în suma ∑ᵢC(m,i)C(n,k−i), toți termenii contribuie mereu cu o valoare pozitivă, pentru orice i de la 0 la k.","pasi":["Dacă i depășește m, atunci C(m,i)=0, pentru că nu putem alege mai multe elemente decât are grupul A.","La fel, dacă k−i depășește n, atunci C(n,k−i)=0, pentru că nu putem alege mai multe elemente decât are grupul B.","De exemplu, la m=4, n=1, k=2, termenul cu i=0 conține C(1,2)=0, deci acel termen nu contribuie deloc la sumă - nu toți termenii sunt pozitivi, unii sunt zero."],"r":"✓ <strong>Fals</strong> - unii termeni pot fi zero, atunci când alegerea depășește mărimea unui grup"},{"q":"O cutie are 5 creioane colorate și 4 creioane simple (9 creioane în total). Un copil vrea să aleagă 3 creioane, fără să conteze de care fel. Arată, folosind identitatea lui Vandermonde, că numărul total de alegeri se poate calcula fie direct din toate cele 9 creioane, fie combinând alegeri separate din cele două tipuri.","pasi":["Direct: numărul de moduri de a alege 3 creioane din cele 9 este C(9,3)=84.","Combinat: numărăm separat câte creioane colorate (i) și câte simple (3−i) alegem, pentru fiecare i de la 0 la 3, și adunăm: C(5,0)C(4,3)+C(5,1)C(4,2)+C(5,2)C(4,1)+C(5,3)C(4,0)=4+30+40+10=84.","Ambele metode dau același rezultat, 84, exact ce prezice identitatea lui Vandermonde."],"r":"✓ <strong>84</strong> moduri, calculate identic pe ambele căi"}]};
CONTINUT_COMBINATORICA["permutari-fara-puncte-fixe-derangements"]={definitie:"<div class=\"def-box\"><strong>Enunț:</strong> Un derajament este o permutare a n elemente în care niciun element nu rămâne pe locul său inițial. Numărul lor este Dₙ=n!·∑_{k=0}^{n} (−1)ᵏ/k!.</div>",formula_display:"Dₙ = n!·∑_{k=0}^{n} (−1)ᵏ/k!",diagrama:"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"arrowhead\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><polygon points=\"0,0 7,3 0,6\" fill=\"#c8922a\"/></marker></defs><text x=\"150\" y=\"16\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#5a1a8a\">D₄: nimeni nu rămâne pe locul inițial</text><line x1=\"50\" y1=\"40\" x2=\"50\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.35\"/><line x1=\"120\" y1=\"40\" x2=\"120\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.35\"/><line x1=\"190\" y1=\"40\" x2=\"190\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.35\"/><line x1=\"260\" y1=\"40\" x2=\"260\" y2=\"160\" stroke=\"#5a1a8a\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.35\"/><line x1=\"50\" y1=\"45\" x2=\"115\" y2=\"153\" stroke=\"#c8922a\" stroke-width=\"2.5\" marker-end=\"url(#arrowhead)\"/><line x1=\"120\" y1=\"45\" x2=\"185\" y2=\"153\" stroke=\"#c8922a\" stroke-width=\"2.5\" marker-end=\"url(#arrowhead)\"/><line x1=\"190\" y1=\"45\" x2=\"255\" y2=\"153\" stroke=\"#c8922a\" stroke-width=\"2.5\" marker-end=\"url(#arrowhead)\"/><path d=\"M260,45 Q150,110 56,153\" fill=\"none\" stroke=\"#c8922a\" stroke-width=\"2.5\" marker-end=\"url(#arrowhead)\"/><circle cx=\"50\" cy=\"40\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"120\" cy=\"40\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"190\" cy=\"40\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"260\" cy=\"40\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"50\" cy=\"160\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"120\" cy=\"160\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"190\" cy=\"160\" r=\"12\" fill=\"#5a1a8a\"/><circle cx=\"260\" cy=\"160\" r=\"12\" fill=\"#5a1a8a\"/><text x=\"50\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">1</text><text x=\"120\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">2</text><text x=\"190\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">3</text><text x=\"260\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">4</text><text x=\"50\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">1</text><text x=\"120\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">2</text><text x=\"190\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">3</text><text x=\"260\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"#ffffff\">4</text><text x=\"150\" y=\"188\" text-anchor=\"middle\" font-size=\"10\" fill=\"#c8922a\">linii punctate = locul propriu (evitat); săgeți aurii = 1→2→3→4→1</text></svg>",intuitiv_text:"4 copii își lasă hainele într-un cuier cu 4 cârlige, unul pentru fiecare copil. La plecare, cârligele se amestecă și fiecare copil ia o haină - dar niciunul nu are voie să ia propria haină înapoi! <span class=\"hl\">Un derajament numără în câte moduri se pot amesteca hainele astfel încât niciun copil să nu-și ia propria haină</span>. Pentru 4 copii există exact 9 asemenea amestecuri posibile.",intuitiv_nota:"Pierre Rémond de Montmort (1708) a studiat problema în contextul jocurilor de cărți (problema „treize”). Formula se obține prin principiul includerii-excluderii.",exercitii:[{"q":"Calculează D₃, numărul de derajamente ale mulțimii {1,2,3}, folosind formula Dₙ=n!·∑_{k=0}^{n}(−1)ᵏ/k!.","pasi":["Calculăm suma pentru n=3: 1−1+1/2−1/6.","Această sumă este egală cu 1/2−1/6=3/6−1/6=2/6=1/3.","Înmulțim cu 3!=6: D₃=6·(1/3)=2; verificăm prin enumerare directă că singurele derajamente ale lui {1,2,3} sunt (2,3,1) și (3,1,2)."],"r":"✓ D₃=<strong>2</strong>"},{"q":"Se știe că D₅=44 și D₄=9. Folosind recurența Dₙ=(n−1)(Dₙ₋₁+Dₙ₋₂), scrisă pentru n=5, află valoarea D₃ mergând înapoi.","pasi":["Recurența pentru n=5 este D₅=(5−1)(D₄+D₃), adică D₅=4(D₄+D₃).","Înlocuim D₅=44 și D₄=9: 44=4(9+D₃), adică 44=36+4D₃.","De aici 4D₃=8, deci D₃=2 - exact valoarea găsită direct la primul exercițiu, confirmând recurența."],"r":"✓ D₃=<strong>2</strong>"},{"q":"Câte derajamente are o mulțime cu 1 singur element? Dar cu 2 elemente?","pasi":["Pentru o mulțime cu 1 element, singura permutare posibilă este cea care lasă elementul pe loc, deci nu există nicio permutare fără puncte fixe: D₁=0.","Pentru o mulțime cu 2 elemente {1,2} există 2 permutări posibile: (1,2), care lasă ambele elemente pe loc, și (2,1), în care niciun element nu rămâne pe loc.","Doar a doua permutare este un derajament, deci D₂=1."],"r":"✓ D₁=<strong>0</strong> și D₂=<strong>1</strong>"},{"q":"Adevărat sau fals: pe măsură ce n crește, este din ce în ce mai probabil ca o permutare aleasă la întâmplare să fie un derajament, apropiindu-se de certitudine.","pasi":["Probabilitatea ca o permutare aleatoare de n elemente să fie derajament este Dₙ/n!.","Pentru n=4, această probabilitate este D₄/4!=9/24=3/8=0,375; pe măsură ce n crește, raportul Dₙ/n! se apropie tot mai mult de 1/e≈0,368, fără să mai crească spre 1.","Deci probabilitatea NU crește constant spre 1 - ea se stabilizează în jurul unei valori fixe, aproximativ 37%, indiferent cât de mare devine n."],"r":"✓ <strong>Fals</strong> - probabilitatea se apropie de o valoare fixă (1/e≈0,368), nu crește spre 1"},{"q":"La o petrecere, 4 copii vin cu câte un cadou împachetat și le pun pe toate pe o masă. La final, fiecare copil trage la întâmplare un cadou de pe masă, dar niciunul nu are voie să ia propriul cadou. În câte moduri diferite se poate întâmpla acest lucru?","pasi":["Această situație corespunde exact numărului de derajamente ale unei mulțimi cu 4 elemente, D₄.","Calculăm D₄=4!·(1−1+1/2−1/6+1/24)=24·(9/24)=9.","Deci există exact 9 moduri diferite în care cadourile pot fi redistribuite astfel încât niciun copil să nu-și primească propriul cadou înapoi."],"r":"✓ <strong>9</strong> moduri diferite"}]};
